<?php require_once 'includes/auth.php';require_customer();$s=db()->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC');$s->execute([$_SESSION['customer_id']]);$os=$s->fetchAll();$title='My Orders - '.APP_NAME;include 'includes/header.php';?><h1>My Orders</h1><table class="table"><tr><th>Order</th><th>Total</th><th>Payment</th><th>Order Status</th><th>Date</th></tr><?php foreach($os as $o):?><tr><td>#<?=$o['id']?></td><td>KES <?=number_format($o['total'],2)?></td><td><?=htmlspecialchars($o['payment_status'])?></td><td><?=htmlspecialchars($o['order_status'])?></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endforeach;?></table><?php include 'includes/footer.php';?>